INSERT INTO pages ("slug", "title", "intro", "body", "image_id", "legacy_wp_id", "seo_title", "seo_description", "status", "system") VALUES ('about-us', 'About Us', 'TALINDIA is your complete workforce development partner, empowering job seekers with industry-ready skills and helping employers build capable teams through custom training solutions. We don’t just train; we transform careers and strengthen businesses.', 'Born from the desire to bridge the gap between education and employability, Talindia was founded by industry experts who understand the real struggles faced by job-seekers and professionals in today’s fast-changing world. We believe everyone deserves the opportunity to unlock their full potential and land their dream job, regardless of background.
